-- Humand deal stages, stage tags, and Lost / Postponed details.
-- 1. Deals get the details of a loss (reason, detail, date) and of a
--    postponement (date to resume, reason, date).
-- 2. A deal can carry tags ("post-its") from a fixed list per stage, each one
--    with an optional short description. Tags are removed when the deal
--    changes stage, and kept in the table as history.
-- 3. Existing deals move from the previous stages to the new ones.
-- 4. The shared configuration gets the new stages and tags.

-- 1. Lost and postponed details
alter table public.deals add column if not exists lost_reason text;
alter table public.deals add column if not exists lost_reason_detail text;
alter table public.deals add column if not exists lost_at timestamp with time zone;
alter table public.deals add column if not exists postponed_until date;
alter table public.deals add column if not exists postponed_reason text;
alter table public.deals add column if not exists postponed_at timestamp with time zone;

-- 2. Stage tags
create table if not exists public.deal_tag_assignments (
    id bigint generated by default as identity primary key,
    deal_id bigint not null,
    stage text not null,
    tag_value text not null,
    description text,
    sales_id bigint,
    created_at timestamp with time zone not null default now(),
    updated_at timestamp with time zone,
    updated_by bigint,
    removed_at timestamp with time zone,
    removed_reason text,
    constraint deal_tag_assignments_description_length check (char_length(description) <= 200),
    constraint deal_tag_assignments_removed_reason_check check (removed_reason in ('stage_change', 'manual'))
);

alter table public.deal_tag_assignments drop constraint if exists deal_tag_assignments_deal_id_fkey;
alter table public.deal_tag_assignments
    add constraint deal_tag_assignments_deal_id_fkey foreign key (deal_id) references public.deals(id) on delete cascade;
alter table public.deal_tag_assignments drop constraint if exists deal_tag_assignments_sales_id_fkey;
alter table public.deal_tag_assignments
    add constraint deal_tag_assignments_sales_id_fkey foreign key (sales_id) references public.sales(id) on delete set null;
alter table public.deal_tag_assignments drop constraint if exists deal_tag_assignments_updated_by_fkey;
alter table public.deal_tag_assignments
    add constraint deal_tag_assignments_updated_by_fkey foreign key (updated_by) references public.sales(id) on delete set null;

create index if not exists deal_tag_assignments_deal_id_idx on public.deal_tag_assignments using btree (deal_id);
-- A tag is applied at most once at a time on a deal
create unique index if not exists deal_tag_assignments_active_unique_idx
    on public.deal_tag_assignments using btree (deal_id, tag_value) where removed_at is null;

alter table public.deal_tag_assignments enable row level security;
drop policy if exists "Enable read access for authenticated users" on public.deal_tag_assignments;
create policy "Enable read access for authenticated users" on public.deal_tag_assignments for select to authenticated using (true);
drop policy if exists "Enable insert for authenticated users only" on public.deal_tag_assignments;
create policy "Enable insert for authenticated users only" on public.deal_tag_assignments for insert to authenticated with check (true);
drop policy if exists "Enable update for authenticated users only" on public.deal_tag_assignments;
create policy "Enable update for authenticated users only" on public.deal_tag_assignments for update to authenticated using (true) with check (true);
drop policy if exists "Deal Tag Assignments Delete Policy" on public.deal_tag_assignments;
create policy "Deal Tag Assignments Delete Policy" on public.deal_tag_assignments for delete to authenticated using (true);

grant all on table public.deal_tag_assignments to anon;
grant all on table public.deal_tag_assignments to authenticated;
grant all on table public.deal_tag_assignments to service_role;
grant all on sequence public.deal_tag_assignments_id_seq to anon;
grant all on sequence public.deal_tag_assignments_id_seq to authenticated;
grant all on sequence public.deal_tag_assignments_id_seq to service_role;

-- 3. Existing deals move to the new stages
create temporary table humand_stage_migration as
select
    id,
    stage as old_stage,
    case stage
        when 'identified' then 'first-contact'
        when 'first-contact' then 'first-contact'
        when 'meeting-scheduled' then 'lead'
        when 'demo-done' then 'discovery'
        when 'proposal-sent' then 'champion'
        when 'in-negociation' then 'negotiation'
        when 'won' then 'won'
        when 'implementation' then 'won'
        when 'lost' then 'lost'
        else 'first-contact'
    end as new_stage,
    case stage
        when 'meeting-scheduled' then 'first-meeting-scheduled'
        when 'proposal-sent' then 'proposal-sent'
        when 'implementation' then 'implementation-in-progress'
    end as new_tag
from public.deals
where stage not in (
    'first-contact', 'lead', 'early-stage', 'discovery', 'champion', 'decision-maker',
    'negotiation', 'pilot', 'agreement', 'won', 'postponed', 'lost'
);

update public.deals d
set stage = m.new_stage,
    lost_reason = case when m.new_stage = 'lost' then coalesce(d.lost_reason, 'unspecified') else d.lost_reason end,
    lost_at = case when m.new_stage = 'lost' then coalesce(d.lost_at, d.updated_at) else d.lost_at end
from humand_stage_migration m
where d.id = m.id;

-- Deals that were already lost keep a reason too
update public.deals
set lost_reason = 'unspecified', lost_at = coalesce(lost_at, updated_at)
where stage = 'lost' and lost_reason is null;

insert into public.deal_tag_assignments (deal_id, stage, tag_value, sales_id, created_at)
select d.id, m.new_stage, m.new_tag, d.sales_id, now()
from humand_stage_migration m
join public.deals d on d.id = m.id
where m.new_tag is not null
on conflict do nothing;

drop table humand_stage_migration;

-- Several previous stages can land in the same new stage: renumber each column
update public.deals d
set index = r.new_index
from (
    select id, (row_number() over (partition by stage order by index nulls last, id) - 1)::smallint as new_index
    from public.deals
) r
where d.id = r.id and d.index is distinct from r.new_index;

-- A lost deal has a reason, a postponed deal has a date and a reason
alter table public.deals drop constraint if exists deals_lost_reason_required;
alter table public.deals
    add constraint deals_lost_reason_required check (stage <> 'lost' or lost_reason is not null);
alter table public.deals drop constraint if exists deals_postponed_details_required;
alter table public.deals
    add constraint deals_postponed_details_required check (
        stage <> 'postponed' or (postponed_until is not null and postponed_reason is not null)
    );

-- Stage changes stamp and clear the lost / postponed details
CREATE OR REPLACE FUNCTION "public"."handle_deal_stage_details"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' or new.stage is distinct from old.stage then
    if new.stage = 'lost' then
      new.lost_at := coalesce(new.lost_at, now());
    else
      new.lost_reason := null;
      new.lost_reason_detail := null;
      new.lost_at := null;
    end if;

    if new.stage = 'postponed' then
      new.postponed_at := coalesce(new.postponed_at, now());
    else
      new.postponed_until := null;
      new.postponed_reason := null;
      new.postponed_at := null;
    end if;
  end if;

  return new;
end;
$$;

-- Moving a deal to another stage removes its tags (they stay as history)
CREATE OR REPLACE FUNCTION "public"."remove_deal_tags_on_stage_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  update public.deal_tag_assignments
  set removed_at = now(), removed_reason = 'stage_change'
  where deal_id = new.id
    and removed_at is null
    and stage is distinct from new.stage;

  return null;
end;
$$;

-- Who created and who last edited a tag
CREATE OR REPLACE FUNCTION "public"."set_deal_tag_assignment_audit"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.sales_id is null then
      select id into new.sales_id from public.sales where user_id = auth.uid();
    end if;
  else
    new.updated_at := now();
    select id into new.updated_by from public.sales where user_id = auth.uid();
  end if;

  return new;
end;
$$;

grant all on function public.handle_deal_stage_details() to anon;
grant all on function public.handle_deal_stage_details() to authenticated;
grant all on function public.handle_deal_stage_details() to service_role;
grant all on function public.remove_deal_tags_on_stage_change() to anon;
grant all on function public.remove_deal_tags_on_stage_change() to authenticated;
grant all on function public.remove_deal_tags_on_stage_change() to service_role;
grant all on function public.set_deal_tag_assignment_audit() to anon;
grant all on function public.set_deal_tag_assignment_audit() to authenticated;
grant all on function public.set_deal_tag_assignment_audit() to service_role;

create or replace trigger handle_deal_stage_details
    before insert or update of stage on public.deals
    for each row execute function public.handle_deal_stage_details();

create or replace trigger remove_deal_tags_on_stage_change
    after update of stage on public.deals
    for each row
    when (old.stage is distinct from new.stage)
    execute function public.remove_deal_tags_on_stage_change();

create or replace trigger set_deal_tag_assignment_audit
    before insert or update on public.deal_tag_assignments
    for each row execute function public.set_deal_tag_assignment_audit();

-- 4. Shared configuration: Humand defaults for the keys never saved from the
-- Settings page, then what was saved, then the new stages and tags.
insert into public.configuration (id, config) values (1, '{}'::jsonb)
on conflict (id) do nothing;

