set config = '{"title":"Humand CRM","currency":"USD","companySectors":[{"value":"accounting-audit","label":"Contabilidad y auditoría"},{"value":"professional-services","label":"Servicios profesionales"},{"value":"retail","label":"Retail y consumo masivo"},{"value":"manufacturing","label":"Industria y manufactura"},{"value":"logistics","label":"Logística y transporte"},{"value":"health-care","label":"Salud"},{"value":"hospitality","label":"Gastronomía y hotelería"},{"value":"financials","label":"Banca y finanzas"},{"value":"information-technology","label":"Tecnología"},{"value":"education","label":"Educación"},{"value":"energy","label":"Energía y minería"},{"value":"construction","label":"Construcción e inmobiliario"},{"value":"public-sector","label":"Sector público"},{"value":"other","label":"Otro"}],"dealCategories":[{"value":"russell-bedford","label":"Russell Bedford"},{"value":"referral","label":"Referido"},{"value":"linkedin","label":"LinkedIn"},{"value":"event","label":"Evento"},{"value":"inbound","label":"Inbound"},{"value":"other","label":"Otro"}],"noteStatuses":[{"value":"cold","label":"Frío","color":"#7dbde8"},{"value":"warm","label":"Tibio","color":"#e8cb7d"},{"value":"hot","label":"Caliente","color":"#e88b7d"},{"value":"in-contract","label":"Cliente","color":"#a4e87d"}],"taskTypes":[{"value":"none","label":"Ninguno"},{"value":"call","label":"Llamada"},{"value":"email","label":"Email"},{"value":"linkedin","label":"LinkedIn"},{"value":"whatsapp","label":"WhatsApp"},{"value":"meeting","label":"Reunión"},{"value":"demo","label":"Demo"},{"value":"follow-up","label":"Seguimiento"}]}'::jsonb
    || config
    || '{"dealStages":[{"value":"first-contact","label":"Primer contacto","humandStage":"Prospección","description":"Antes del pipeline de Humand: primer mensaje o llamada a la empresa, todavía sin respuesta o sin reunión."},{"value":"lead","label":"Lead","humandStage":"Lead","description":"La empresa respondió y hay interés en conocer Humand. Se busca agendar la primera reunión."},{"value":"early-stage","label":"Early stage","humandStage":"Early Stage","description":"Hubo una primera reunión, pero sin interés explícito, con implementación a más de 6 meses o con una reunión corta."},{"value":"discovery","label":"Coordinación · Discovery","humandStage":"Discovery","description":"Se entienden los dolores, procesos y herramientas actuales de la empresa y se identifica a quiénes deciden."},{"value":"champion","label":"2da call · Champion","humandStage":"Champion Engaged","description":"Hay una persona interna que impulsa el proyecto (champion) y participa de la segunda reunión."},{"value":"decision-maker","label":"3ra call · Decision maker","humandStage":"Decision Maker Engaged","description":"Participa quien toma la decisión final. Puede incluir llamadas técnicas con IT o a Compras."},{"value":"negotiation","label":"Negociación","humandStage":"Decision Maker Engaged","description":"Se trabaja el business case, la urgencia y el precio con quien decide. Todavía no se envió el contrato."},{"value":"pilot","label":"Piloto","humandStage":"Pilot","description":"Camino opcional: se hizo el kick-off del piloto y la implementación arranca antes de firmar. El contrato aún no se envió."},{"value":"agreement","label":"Acuerdo / contrato","humandStage":"Final Negotiation","description":"Empieza cuando se envía el contrato: revisión legal, descuentos, condiciones de pago y facturación."},{"value":"won","label":"Ganado","humandStage":"Won","description":"El contrato se firmó o llegó el primer pago. La implementación puede haber empezado antes (piloto) o empezar ahora."},{"value":"postponed","label":"Pospuesto","humandStage":"Postponed","description":"La empresa pidió retomar más adelante. Se registra la fecha para volver a contactarla y el motivo."},{"value":"lost","label":"Perdido","humandStage":"Lost","description":"Dijo que no explícitamente, o no respondió a 5-7 seguimientos a lo largo de al menos 3 meses."}],"dealPipelineStatuses":["won","postponed","lost"],"dealStageTags":[{"stage":"first-contact","value":"no-response","label":"Sin respuesta","color":"#f2c6c2"},{"stage":"first-contact","value":"replied","label":"Respondió","color":"#c6e8c2"},{"stage":"lead","value":"first-meeting-scheduled","label":"1ra reunión agendada","color":"#c6dcf2"},{"stage":"lead","value":"no-show","label":"No se presentó","color":"#f2c6c2"},{"stage":"lead","value":"no-fit","label":"No fit","color":"#e0d4c4"},{"stage":"early-stage","value":"implements-6m","label":"Implementa en +6 meses","color":"#f2e3b3"},{"stage":"early-stage","value":"no-explicit-interest","label":"Sin interés explícito","color":"#e0d4c4"},{"stage":"early-stage","value":"short-meeting","label":"Reunión de menos de 30 min","color":"#f2d8b3"},{"stage":"early-stage","value":"reactivate-later","label":"Reactivar más adelante","color":"#d9cdf2"},{"stage":"discovery","value":"pain-identified","label":"Dolor identificado","color":"#c6e8c2"},{"stage":"discovery","value":"missing-decision-makers","label":"Faltan decisores","color":"#f2d8b3"},{"stage":"champion","value":"second-meeting-scheduled","label":"2da reunión agendada","color":"#c6dcf2"},{"stage":"champion","value":"second-meeting-pending","label":"2da reunión sin agendar","color":"#f2d8b3"},{"stage":"champion","value":"proposal-sent","label":"Propuesta enviada","color":"#d9cdf2"},{"stage":"decision-maker","value":"third-meeting-scheduled","label":"3ra reunión agendada","color":"#c6dcf2"},{"stage":"decision-maker","value":"third-meeting-pending","label":"Sin agendar","color":"#f2d8b3"},{"stage":"decision-maker","value":"it-technical-call","label"